-- f-content-seeds t-86: her seven foundational documents, written into the
-- tables `20260927100000_app_foundational_documents` created, so that every
-- environment has them the moment it migrates.
--
-- WHY A MIGRATION AND NOT ONLY THE SEED (owner rule, 22 September 2026;
-- `.context/app/database-changes.md`). Production runs `db:migrate:deploy`
-- before every start and runs the seeder only when someone asks. From t-86 every
-- public page, the acknowledgement gate and both emails read these tables, so an
-- environment that migrated but was not seeded would answer 500 on all of them.
-- This migration is what reaches every existing database. The seed unit
-- (`prisma/seeds/app-lelanea/015-foundational-documents.ts`) writes the same
-- rows and is written to find them here and do nothing.
--
-- WHAT IT WRITES is exactly what the seed writes: the JSON below is
-- `buildFoundationalSeed()` (`lib/app/content/foundational-seed.ts`), generated
-- from `content/lelanea_foundational_documents.json` with the owner's section
-- keys on the blocks. `tests/unit/lib/app/content/foundational-seed.test.ts`
-- parses it back out of this file and fails if it differs from what the seed
-- would write today.
--
-- Rows are operator-owned (`fp4`), so each insert runs only while its table is
-- empty. The tables were created one migration earlier, so in practice they
-- always are; the guard is what keeps this safe to read as idempotent. Every
-- document gets revision 1 with `origin = 'seed'` and a null `editorId`,
-- because the operator wrote it, not a person. Revision ids are UUIDs, as in
-- `20260926100000_app_health_slots_sensitive`: the column is TEXT and nothing
-- parses it.
--
-- Data only: no schema diff. Apply with `npm run db:migrate:deploy`, then
-- `npm run db:drift-check`.

CREATE TEMP TABLE "_t86_seed" AS SELECT $t86${"collection":{"id":"lelanea_app_foundational_documents","title":"Lelañea — Foundational Documents","version":"1.1","locale":"en-US"},"documents":[{"id":"the_initiation","position":0,"title":"The Initiation","subtitle":"Lelañea App Welcome Statement","category":"onboarding","surface":"first_run_welcome","requiresAcknowledgement":false,"placeholders":["{{first_name}}"],"renderStyle":"cadence","renderNote":"Single-sentence paragraphs are an intentional stylistic cadence. Render each as its own line or beat; do not merge them into flowing prose.","blocks":[{"type":"paragraph","text":"Welcome, {{first_name}}.","section":"welcome"},{"type":"paragraph","text":"I am so incredibly grateful you’re here.","section":"welcome"},{"type":"paragraph","text":"Whether you realize it or not, something within you has called you to this moment.","section":"welcome"},{"type":"paragraph","text":"Perhaps it arrived as curiosity, a longing for something more, a desire for a great shift to occur, or even from frustration that this human experience isn’t in alignment with what you internally know is possible. We all know that little whisper inside of us that says, “this can’t possibly be it. There has to be more to this life.”","section":"welcome"},{"type":"paragraph","text":"Whatever it is that brought you here, you listened.","section":"welcome"},{"type":"paragraph","text":"And that matters.","section":"welcome"},{"type":"paragraph","text":"Welcome to Lelañea.","section":"welcome"},{"type":"paragraph","text":"This is not simply an app.","section":"invitation"},{"type":"paragraph","text":"It is an invitation.","section":"invitation"},{"type":"paragraph","text":"An invitation to explore the relationship you have with yourself, your consciousness, and the magnificent intelligence that has always existed beneath the noise of the human experience.","section":"invitation"},{"type":"paragraph","text":"For centuries, we have been taught to understand ourselves through limitation.","section":null},{"type":"paragraph","text":"We have learned to identify with our labels, our accomplishments, our fears, our wounds, our beliefs, and the stories we inherited long before we were ever conscious enough to question them.","section":null},{"type":"paragraph","text":"Slowly, almost invisibly, we began to mistake the conditioned self for our true nature.","section":null},{"type":"paragraph","text":"Yet throughout the wisdom traditions of our world, from the Hermetic teachings of ancient Egypt and Greece to the Vedas and Vedanta of India, to the mystics who have spoken of unity throughout history, there exists a common thread.","section":null},{"type":"paragraph","text":"And that is… the possibility that we are infinitely more than we appear to be.","section":null},{"type":"paragraph","text":"That beneath the personality lives consciousness.","section":null},{"type":"paragraph","text":"Beneath fear lives love.","section":null},{"type":"paragraph","text":"Beneath conditioning lives awareness.","section":null},{"type":"paragraph","text":"And beneath the lowercase self—known as the ego—exists the capital Self, or Higher Self.","section":null},{"type":"paragraph","text":"Which is not something to become.","section":null},{"type":"paragraph","text":"But rather, something to remember.","section":null},{"type":"paragraph","text":"You, {{first_name}}, are far more powerful than you know.","section":null},{"type":"paragraph","text":"Like every one of our brothers and sisters walking this Earth, we often forget that we possess the extraordinary capacity to consciously participate in the unfolding of our lives.","section":null},{"type":"paragraph","text":"To create.","section":null},{"type":"paragraph","text":"To transform.","section":null},{"type":"paragraph","text":"To heal.","section":null},{"type":"paragraph","text":"And even to transcend.","section":null},{"type":"paragraph","text":"To move into greater harmony with ourselves, with one another, and with the greater intelligence that has always been moving through life itself.","section":null},{"type":"paragraph","text":"This journey is not about becoming someone else.","section":null},{"type":"paragraph","text":"It is about remembering who you have always been beneath the conditioning. This leads us to “Purpose,” which is often imagined as something waiting somewhere outside of us.","section":null},{"type":"paragraph","text":"A career.","section":null},{"type":"paragraph","text":"A mission.","section":null},{"type":"paragraph","text":"A destination.","section":null},{"type":"paragraph","text":"Yet purpose is first an internal experience.","section":null},{"type":"paragraph","text":"It begins in the relationship you cultivate with yourself.","section":null},{"type":"paragraph","text":"Every belief you transform.","section":null},{"type":"paragraph","text":"Every unconscious pattern you illuminate.","section":null},{"type":"paragraph","text":"Every shadow you meet and accept with compassion.","section":null},{"type":"paragraph","text":"Every story you release.","section":null},{"type":"paragraph","text":"And every gentle shift in the clarity of self-awareness.","section":null},{"type":"paragraph","text":"This is purpose.","section":null},{"type":"paragraph","text":"When we understand and actuate our purpose internally, we naturally begin to externalize it. This is called expression, which may become a business, a family, a work of art, a quiet life of service, contributions to societal shifts, visionary accomplishments, or something the world never sees or even applauds.","section":null},{"type":"paragraph","text":"Expression is unique to you, as your vehicle is a unique expression of consciousness.","section":null},{"type":"paragraph","text":"Purpose is universal, and it begins within.","section":null},{"type":"paragraph","text":"I am your personal guide, and together we will move in tandem as we explore the beliefs, identities, emotional patterns, language, perceptions, and unconscious systems that quietly shape your reality.","section":null},{"type":"paragraph","text":"Not because these parts of you are broken.","section":null},{"type":"paragraph","text":"Not because they need fixing.","section":null},{"type":"paragraph","text":"But because they deserve to be seen.","section":null},{"type":"paragraph","text":"What is seen can be understood.","section":null},{"type":"paragraph","text":"What is understood can be transformed or alchemized.","section":null},{"type":"paragraph","text":"And what is transformed creates new possibilities for the life you are here to live.","section":null},{"type":"paragraph","text":"My role is not to tell you who you are.","section":"guide"},{"type":"paragraph","text":"It is to walk beside you as you begin to remember you.","section":"guide"},{"type":"paragraph","text":"To offer perspectives.","section":"guide"},{"type":"paragraph","text":"Practices.","section":"guide"},{"type":"paragraph","text":"Questions.","section":"guide"},{"type":"paragraph","text":"Ancient wisdom.","section":"guide"},{"type":"paragraph","text":"Modern understanding.","section":"guide"},{"type":"paragraph","text":"And experiences that invite you into deeper awareness of your own truth.","section":"guide"},{"type":"paragraph","text":"There is nothing you are required to believe.","section":"guide"},{"type":"paragraph","text":"Only experiences to have.","section":null},{"type":"paragraph","text":"Perspectives to explore.","section":null},{"type":"paragraph","text":"Practices to embody.","section":null},{"type":"paragraph","text":"And a relationship with yourself waiting to deepen.","section":null},{"type":"paragraph","text":"Your journey is powerful.","section":null},{"type":"paragraph","text":"Your journey is sacred.","section":null},{"type":"paragraph","text":"Your journey is entirely your own.","section":null},{"type":"paragraph","text":"And I am deeply honored to walk beside you as you discover the extraordinary being you have always been.","section":null},{"type":"paragraph","text":"Welcome to Lelañea.","section":null},{"type":"paragraph","text":"Let’s begin your journey.","section":null}],"version":"1.1","locale":"en-US"},{"id":"the_heart_behind_lelanea","position":1,"title":"The Heart Behind Lelañea","subtitle":"The Intent and Mission of Lelañea","category":"about","surface":"about_philosophy","requiresAcknowledgement":false,"placeholders":[],"renderStyle":null,"renderNote":null,"blocks":[{"type":"paragraph","text":"Lelañea was created as an invitation into conscious living.","section":"invitation"},{"type":"paragraph","text":"Its purpose is not simply to help individuals improve themselves, but to support them in remembering who they are beneath conditioning, inherited beliefs, unconscious patterns, and the countless identities accumulated throughout life.","section":"purpose"},{"type":"paragraph","text":"At its heart, Lelañea is a transcendental coaching experience. It invites each individual to explore the relationship between the lowercase self—the conditioned personality shaped by experiences, culture, family systems, and survival—and the capital Self, the deeper awareness that many contemplative traditions describe as our authentic nature.","section":null},{"type":"paragraph","text":"Rather than focusing solely on symptom reduction or external achievement, Lelañea encourages the cultivation of self-awareness, discernment, compassion, integrity, and conscious choice. Through reflective practices, contemplative exercises, guided meditations, values clarification, mindset exploration, nervous system awareness, shadow inquiry, and intentional action, users are invited to examine the internal landscape from which every external experience emerges.","section":null},{"type":"paragraph","text":"The philosophy of Lelañea recognizes that our internal world shapes the way we perceive ourselves, relate to others, and participate in life. As awareness expands, greater freedom becomes possible. As unconscious patterns become conscious, new choices emerge. As those choices become embodied, life begins to reflect a deeper alignment with authenticity.","section":null},{"type":"paragraph","text":"Lelañea does not ask its users to adopt a particular belief system.","section":null},{"type":"paragraph","text":"Instead, it offers perspectives, practices, and questions that encourage thoughtful exploration. Every individual is invited to retain their own discernment, integrating only what resonates with their lived experience and personal truth.","section":null},{"type":"paragraph","text":"Transformation is not viewed as becoming someone new.","section":"remembrance"},{"type":"paragraph","text":"It is the continual remembrance of who we have always been.","section":"remembrance"}],"version":"1.1","locale":"en-US"},{"id":"the_mission","position":2,"title":"The Mission","subtitle":null,"category":"about","surface":"about_mission","requiresAcknowledgement":false,"placeholders":[],"renderStyle":null,"renderNote":null,"blocks":[{"type":"paragraph","text":"Coach Lelañea Fulton believes that the journey inward should never be reserved for the privileged. For generations, profound personal transformation has often been hidden behind financial barriers. One-on-one coaching, retreats, intensive programs, and private mentorship have provided life-changing experiences for many, yet they remain inaccessible to millions of individuals who long for this work but simply cannot afford it.","section":null},{"type":"paragraph","text":"The Lelañea App was created to help change that. Its mission is to make transcendental coaching, contemplative self-inquiry, and consciousness-expanding practices accessible to anyone who feels called to explore the deeper dimensions of themselves, regardless of their financial means.","section":null},{"type":"paragraph","text":"Coach Lelañea believes that every human being deserves access to the tools that cultivate greater self-awareness, emotional freedom, discernment, compassion, integrity, and authentic living. The opportunity to remember who we are, to examine our conditioning, to transform inherited patterns, and to become conscious participants in our own human experience should never depend solely upon economic circumstance.","section":null},{"type":"paragraph","text":"This app exists because transformation should not belong exclusively to those who can afford private coaching. It belongs to humanity.","section":null},{"type":"paragraph","text":"Lelañea often says that purpose is not something we discover somewhere outside ourselves. Purpose begins within. The work we do internally becomes the foundation from which every external expression of our lives naturally unfolds.","section":null},{"type":"paragraph","text":"The vision of The Lelañea App extends far beyond individual transformation. It is rooted in the understanding that as individuals become more conscious, compassionate, self-aware, and internally aligned, they naturally influence their families, communities, workplaces, institutions, and cultures. One awakened life has the potential to influence countless others.","section":null},{"type":"paragraph","text":"Coach Lelañea believes that when enough individuals courageously turn inward, examine their own conditioning, and choose to live from greater awareness rather than unconscious programming, humanity has the opportunity to participate in a profound collective evolution.","section":null},{"type":"paragraph","text":"Such an evolution reaches far beyond personal fulfillment.","section":null},{"type":"paragraph","text":"It has the potential to reshape how we educate our children, how we lead our organizations, how we resolve conflict, how we build our economies, how we care for one another, and how we relate to every living being that shares this planet with us.","section":null},{"type":"paragraph","text":"Rather than remaining imprisoned by inherited beliefs, unconscious fear, and stories of limitation, each individual can begin reclaiming their capacity to consciously participate in the creation of their own human experience. This inner work is not an escape from the world. It is a deeper engagement with it.","section":null},{"type":"paragraph","text":"At the heart of Coach Lelañea’s work is the understanding that the greatest transformation available to humanity is not external. It is internal. The human being is the temple, one of many through which consciousness experiences itself. It is through this human experience that we encounter love, compassion, creativity, discernment, and the hidden wisdom that so many traditions have pointed toward throughout history.","section":null},{"type":"paragraph","text":"From this perspective, what many describe as “Heaven on Earth” is not a distant destination waiting somewhere beyond us. It is a way of being that becomes increasingly available as we cultivate awareness, embody compassion, and remember our interconnectedness with all life.","section":null},{"type":"paragraph","text":"This is the vision that inspired The Lelañea App. Not simply to create another self-development app. But to contribute, in whatever way it can, to a more conscious humanity—one person, one family, one community, and one act of awareness at a time.","section":null},{"type":"paragraph","text":"If this work reaches millions of people, Coach Lelañea hopes it will do more than change individual lives. She hopes it will help inspire a world in which greater awareness gives rise to greater compassion, wiser choices, healthier relationships, more conscious leadership, deeper reverence for all sentient life, and a future in which humanity remembers that the power to transform our experience has always begun within.","section":null}],"version":"1.1","locale":"en-US"},{"id":"about_the_creator","position":3,"title":"About the Creator","subtitle":null,"category":"about","surface":"about_creator","requiresAcknowledgement":false,"placeholders":[],"renderStyle":null,"renderNote":null,"blocks":[{"type":"paragraph","text":"Lelañea Fulton is a Transcendental Coach, Unity-Consciousness Guide, Professional Certified Coach (PCC), writer, podcast host, speaker, philanthropist, and lifelong student of consciousness.","section":null},{"type":"paragraph","text":"Her work emerged through the convergence of professional coaching, years of corporate leadership, contemplative study, profound mystical experiences of Oneness, and a childhood near-death experience that fundamentally transformed her understanding of reality, identity, and the nature of human consciousness.","section":null},{"type":"paragraph","text":"With more than fifteen years of experience in leadership, business development, legal operations, and organizational strategy, Lelañea understands both the external demands of modern life and the internal longing for meaning that often accompanies personal success.","section":null},{"type":"paragraph","text":"As the founder of Integrating Consciousness Coaching, she developed a transcendental coaching approach that supports individuals in moving beyond fear-based narratives, inherited conditioning, unconscious patterns, and limiting identities. Rather than viewing human beings as problems to be solved, her work recognizes each individual as inherently whole, possessing an innate capacity for awareness, wisdom, creativity, and transformation.","section":null},{"type":"paragraph","text":"Her coaching integrates professional coaching methodologies with contemplative philosophy, meditation, nervous system awareness, pattern recognition, symbolic inquiry, and lived experiences of Unity Consciousness. While informed by psychology, her work is not intended to replicate Western psychological models. Instead, it approaches human transformation through the philosophical lens of nonduality, Advaita Vedanta, contemplative inquiry, and the understanding that consciousness itself is the primary ground from which meaningful change emerges.","section":null},{"type":"paragraph","text":"Lelañea describes herself first and foremost as a student. A lifelong student of consciousness. A devoted student of Carl Jung and his work on symbolism, archetypes, individuation, and the unconscious. A student of Advaita Vedanta, contemplative traditions, meditation, Hermetic philosophy, systems thinking, and the ever-evolving dialogue between science and spirituality.","section":null},{"type":"paragraph","text":"Her work continues to evolve through study, direct experience, coaching, research, and the countless individuals whose lives continually deepen her understanding of what it means to be fully human.","section":null},{"type":"paragraph","text":"Lelañea represents her ongoing contribution to that exploration.","section":null},{"type":"paragraph","text":"She currently maintains a 1:1 practice where she works with clients supporting transcendental shifts. She is a writer and continues to publish on Substack. She has two podcasts designed to support the collective. She hosts a free monthly workshop virtually, allowing those who are seeking support around their inner work to inquire more deeply.","section":null}],"version":"1.1","locale":"en-US"},{"id":"the_lineage_of_lelanea","position":4,"title":"The Lineage of Lelañea","subtitle":null,"category":"about","surface":"about_lineage","requiresAcknowledgement":false,"placeholders":[],"renderStyle":null,"renderNote":null,"blocks":[{"type":"paragraph","text":"The Lelañea App was never intended to present itself as a completely original body of work.","section":null},{"type":"paragraph","text":"Like every meaningful discipline, philosophy, or tradition, it exists because of the wisdom, courage, curiosity, and generosity of those who came before.","section":null},{"type":"paragraph","text":"Every reflection, exercise, meditation, coaching framework, journaling prompt, and contemplative practice within this app has been influenced by centuries of philosophical inquiry, scientific research, contemplative traditions, educational methodologies, and modern coaching practices.","section":null},{"type":"paragraph","text":"Lelañea Fulton believes that intellectual integrity requires acknowledging this lineage with gratitude and humility. Among the many individuals, traditions, and disciplines that have shaped The Lelañea App are:","section":null},{"type":"heading","text":"Values Clarification and Values-Based Living","level":2,"section":null},{"type":"paragraph","text":"Louis Raths, Sidney Simon, Merrill Harmin, and John Dewey, whose pioneering work established many of the reflective values exercises used throughout education and coaching today.","section":null},{"type":"heading","text":"Professional Coaching","level":2,"section":null},{"type":"paragraph","text":"The International Coaching Federation (ICF) and the Whole Person Coaching® methodology created by Feroshia Knight, which emphasize presence, curiosity, ethics, reflective inquiry, and whole-person development.","section":null},{"type":"heading","text":"Depth Psychology","level":2,"section":null},{"type":"paragraph","text":"Carl Jung’s work on individuation, symbolism, archetypes, projection, dreams, and shadow integration has profoundly influenced the reflective practices throughout The Lelañea App.","section":null},{"type":"heading","text":"Parts Work","level":2,"section":null},{"type":"paragraph","text":"Dr. Richard Schwartz’s Internal Family Systems model has inspired compassionate approaches to understanding the many aspects of our internal experience.","section":null},{"type":"heading","text":"Transpersonal and Humanistic Psychology","level":2,"section":null},{"type":"paragraph","text":"The work of Abraham Maslow, Roberto Assagioli, Stanislav Grof, Viktor Frankl, and others who expanded psychology beyond pathology toward meaning, purpose, transcendence, and human potential.","section":null},{"type":"heading","text":"Trauma, Somatics, and Nervous System Regulation","level":2,"section":null},{"type":"paragraph","text":"The research and clinical contributions of Dr. Stephen Porges, Deb Dana, Dr. Peter Levine, Dr. Bessel van der Kolk, and Pat Ogden have informed the app’s understanding of regulation, embodiment, and compassionate self-awareness.","section":null},{"type":"heading","text":"Meditation and Contemplative Practice","level":2,"section":null},{"type":"paragraph","text":"The teachings of Jon Kabat-Zinn, Thich Nhat Hanh, Jack Kornfield, Tara Brach, Sharon Salzberg, and Tracee Stanley have contributed to the meditation, mindfulness, and contemplative practices found throughout the app.","section":null},{"type":"heading","text":"Consciousness and Human Flourishing","level":2,"section":null},{"type":"paragraph","text":"The work of Dr. Lisa Miller, David Bohm, Iain McGilchrist, Donald Hoffman, Dean Radin, Rupert Sheldrake, Martin Seligman, Mihaly Csikszentmihalyi, and Barbara Fredrickson has informed many of the conversations surrounding consciousness, resilience, meaning, perception, and human flourishing.","section":null},{"type":"paragraph","text":"Where scientific consensus is still evolving, Lelañea presents these perspectives as opportunities for thoughtful exploration rather than established fact.","section":null},{"type":"heading","text":"Ancient Wisdom Traditions","level":2,"section":null},{"type":"paragraph","text":"Perhaps the deepest influence upon Lelañea comes from the timeless contemplative traditions that have explored consciousness for thousands of years, including Advaita Vedanta, the Upanishads, the Bhagavad Gita, the Yoga Sutras of Patanjali, Buddhism, Taoism, Hermetic philosophy, Christian mysticism, Sufism, and the enduring wisdom of Indigenous cultures around the world.","section":null},{"type":"paragraph","text":"Although these traditions differ in language and practice, they each invite humanity toward greater awareness, compassion, presence, self-inquiry, and an understanding of our profound interconnectedness.","section":null},{"type":"heading","text":"An Evolving Body of Work","level":2,"section":null},{"type":"paragraph","text":"Lelañea is not a finished system.","section":null},{"type":"paragraph","text":"It is a living body of work.","section":null},{"type":"paragraph","text":"As new research emerges, as contemplative understanding continues to deepen, and as Lelañea Fulton continues her own lifelong study of consciousness, philosophy, coaching, neuroscience, and spirituality, the app will continue to evolve.","section":null},{"type":"paragraph","text":"Many of the foundational practices within Lelañea are inspired by established disciplines and respected teachers. As users progress into the later Spiritual Oneness modules, they will encounter Lelañea’s own original frameworks and teachings. These emerge from years of professional coaching, contemplative practice, direct experiences of Unity Consciousness, and her continuing exploration of nondual awareness through the lens of Advaita Vedanta and transcendental inquiry.","section":null},{"type":"paragraph","text":"The Lelañea App is not offered as the definitive path. It is offered as one sincere contribution to humanity’s ongoing exploration of consciousness.","section":null},{"type":"paragraph","text":"May it encourage curiosity.","section":null},{"type":"paragraph","text":"May it deepen compassion.","section":null},{"type":"paragraph","text":"May it strengthen discernment.","section":null},{"type":"paragraph","text":"And above all, may it help each individual remember that the greatest teacher they will ever encounter has always existed within.","section":null}],"version":"1.1","locale":"en-US"},{"id":"disclaimer","position":5,"title":"The Lelañea App","subtitle":"What It Is, What It Is Not, and Important Disclosures","category":"legal","surface":"legal_disclaimer","requiresAcknowledgement":true,"placeholders":[],"renderStyle":null,"renderNote":null,"blocks":[{"type":"paragraph","text":"Please read this section carefully before using Lelañea.","section":null},{"type":"paragraph","text":"By accessing or using this application, you acknowledge that you have read, understood, and agreed to the information contained within this disclaimer.","section":null},{"type":"heading","text":"The Purpose of Lelañea","level":2,"section":"purpose"},{"type":"paragraph","text":"Lelañea is an educational, contemplative, and personal development application created by **Lelañea Fulton**, a **Transcendental Coach** and **Unity-Consciousness Guide**.","section":"purpose"},{"type":"paragraph","text":"The app has been designed to support self-awareness, conscious living, values clarification, reflective inquiry, meditation, personal growth, and transcendental coaching through educational content, guided exercises, contemplative practices, journaling, and coaching methodologies.","section":"purpose"},{"type":"paragraph","text":"Its purpose is to encourage thoughtful self-exploration and conscious personal development.","section":"purpose"},{"type":"paragraph","text":"Lelañea is not intended to provide healthcare, mental healthcare, psychotherapy, or crisis intervention.","section":"purpose_limits"},{"type":"heading","text":"What Lelañea Is Not","level":2,"section":"is_not"},{"type":"paragraph","text":"Lelañea is **not** a medical application.","section":"is_not"},{"type":"paragraph","text":"Lelañea is **not** a mental health application.","section":"is_not"},{"type":"paragraph","text":"Lelañea is **not** a psychotherapy platform.","section":"is_not"},{"type":"paragraph","text":"Lelañea is **not** a counseling service.","section":"is_not"},{"type":"paragraph","text":"Lelañea is **not** psychiatric care.","section":"is_not"},{"type":"paragraph","text":"Lelañea is **not** psychological treatment.","section":"is_not"},{"type":"paragraph","text":"Lelañea is **not** a substitute for professional medical or mental healthcare.","section":"is_not"},{"type":"paragraph","text":"Although some concepts discussed within the app may reference established psychological theories, neuroscience, coaching methodologies, contemplative traditions, philosophy, or spiritual practices, all content is presented for educational and personal development purposes only.","section":"is_not_context"},{"type":"heading","text":"About the Creator","level":2,"section":null},{"type":"paragraph","text":"Lelañea Fulton is a **Professional Certified Coach (PCC)** through the International Coaching Federation (ICF), a **Transcendental Coach**, and a **Unity-Consciousness Guide**.","section":null},{"type":"paragraph","text":"She is **not** a licensed psychologist.","section":null},{"type":"paragraph","text":"She is **not** a licensed psychiatrist.","section":null},{"type":"paragraph","text":"She is **not** a licensed psychotherapist.","section":null},{"type":"paragraph","text":"She is **not** a licensed clinical social worker.","section":null},{"type":"paragraph","text":"She is **not** a licensed professional counselor.","section":null},{"type":"paragraph","text":"She is **not** a physician or medical doctor.","section":null},{"type":"paragraph","text":"She does not diagnose medical conditions, psychiatric disorders, or psychological conditions.","section":null},{"type":"paragraph","text":"She does not prescribe medications.","section":null},{"type":"paragraph","text":"She does not provide psychotherapy.","section":null},{"type":"paragraph","text":"She does not provide psychiatric treatment.","section":null},{"type":"paragraph","text":"She does not provide medical treatment.","section":null},{"type":"paragraph","text":"Nothing contained within Lelañea should be interpreted as establishing a therapist-client relationship, psychologist-patient relationship, physician-patient relationship, or any other licensed healthcare relationship.","section":null},{"type":"paragraph","text":"Your use of this application creates only an educational relationship between you and the platform.","section":null},{"type":"heading","text":"Coaching Is Different from Therapy","level":2,"section":"coaching"},{"type":"paragraph","text":"Transcendental coaching is a personal development modality.","section":"coaching"},{"type":"paragraph","text":"Therapy and psychotherapy are licensed healthcare professions.","section":"coaching"},{"type":"paragraph","text":"Although coaching and therapy may both involve meaningful conversations and self-reflection, they serve different purposes.","section":"coaching"},{"type":"paragraph","text":"Coaching focuses on awareness, intentional living, values, personal responsibility, conscious decision-making, self-exploration, and future growth.","section":"coaching"},{"type":"paragraph","text":"Therapy and psychotherapy are licensed clinical professions that assess, diagnose, and treat mental health conditions and psychological disorders.","section":"coaching"},{"type":"paragraph","text":"Lelañea is intended to complement—not replace—the work of qualified healthcare professionals where appropriate.","section":"coaching"},{"type":"heading","text":"No Diagnosis or Treatment","level":2,"section":null},{"type":"paragraph","text":"Nothing within this application should be interpreted as:","section":null},{"type":"list","style":"unordered","items":["medical advice;","psychological advice;","psychiatric advice;","psychotherapy;","counseling;","diagnosis;","treatment;","crisis intervention;","medication management; or","a substitute for licensed professional care."],"section":null},{"type":"paragraph","text":"The exercises, meditations, reflections, and educational materials are offered solely for personal growth and self-exploration.","section":null},{"type":"heading","text":"Mental Health Conditions","level":2,"section":null},{"type":"paragraph","text":"If you have been diagnosed with a mental health condition—or believe you may be experiencing one—you are strongly encouraged to seek care from a licensed psychologist, psychiatrist, psychotherapist, counselor, physician, or other appropriately qualified healthcare professional.","section":null},{"type":"paragraph","text":"Lelañea is not designed to diagnose, monitor, or treat mental illness.","section":null},{"type":"paragraph","text":"Any decisions regarding medications, treatment plans, diagnoses, or mental healthcare should always be made with a licensed healthcare provider.","section":null},{"type":"heading","text":"Crisis Situations","level":2,"section":"crisis"},{"type":"paragraph","text":"Lelañea is **not** a crisis service.","section":"crisis"},{"type":"paragraph","text":"If you are experiencing:","section":"crisis"},{"type":"list","style":"unordered","items":["thoughts of suicide;","thoughts of self-harm;","thoughts of harming another person;","a psychiatric emergency;","severe depression;","hallucinations;","delusions;","mania;","inability to care for yourself; or","any situation that places you or another person at immediate risk,"],"section":"crisis"},{"type":"paragraph","text":"stop using this application immediately.","section":"crisis"},{"type":"paragraph","text":"Contact your local emergency services, go to your nearest emergency department, or contact a licensed mental health crisis service in your area without delay.","section":"crisis"},{"type":"paragraph","text":"Do not rely on Lelañea during a medical or mental health emergency.","section":"crisis"},{"type":"heading","text":"Spiritual Perspectives","level":2,"section":null},{"type":"paragraph","text":"Lelañea explores themes including consciousness, contemplative traditions, Advaita Vedanta, Unity Consciousness, meditation, symbolism, philosophy, spirituality, and transcendental inquiry.","section":null},{"type":"paragraph","text":"Many of these subjects involve philosophical, contemplative, metaphysical, and spiritual perspectives that are not universally accepted and should not be interpreted as established scientific or medical fact.","section":null},{"type":"paragraph","text":"Users are encouraged to exercise personal discernment and engage thoughtfully with all material presented within the app.","section":null},{"type":"heading","text":"Personal Responsibility","level":2,"section":null},{"type":"paragraph","text":"Your participation in Lelañea is entirely voluntary.","section":null},{"type":"paragraph","text":"You remain solely responsible for your own decisions, interpretations, actions, health, wellbeing, and outcomes arising from your use of this application.","section":null},{"type":"paragraph","text":"While Lelañea aims to support meaningful reflection and personal growth, no specific results or outcomes are promised or guaranteed. Personal growth is a highly individual process influenced by many factors beyond the scope of this app.","section":null},{"type":"heading","text":"Medical Care","level":2,"section":null},{"type":"paragraph","text":"Never delay seeking medical care, mental healthcare, psychiatric treatment, or emergency assistance because of information contained within Lelañea.","section":null},{"type":"paragraph","text":"If you have concerns about your physical health, mental health, medications, diagnosis, or treatment plan, consult an appropriately licensed healthcare professional.","section":null},{"type":"heading","text":"Our Commitment","level":2,"section":null},{"type":"paragraph","text":"Lelañea was created with deep respect for both contemplative wisdom and modern healthcare.","section":"commitment"},{"type":"paragraph","text":"The intention of this app is not to replace licensed professionals, but to provide accessible transcendental coaching, reflective education, and contemplative practices that may complement an individual’s broader journey of personal growth and wellbeing.","section":"commitment"},{"type":"paragraph","text":"Lelañea Fulton believes that coaching, self-awareness, and conscious living can exist alongside psychotherapy, psychiatry, medicine, and other professional healthcare services. These disciplines are not mutually exclusive; they often serve different roles and, when appropriate, may work together in supporting the whole person.","section":null}],"version":"1.1","locale":"en-US"},{"id":"terms_of_use","position":6,"title":"Lelañea™","subtitle":"Terms of Use","category":"legal","surface":"legal_terms","requiresAcknowledgement":true,"placeholders":["[Month Day, Year]","[Support Email]"],"renderStyle":null,"renderNote":null,"blocks":[{"type":"paragraph","text":"**Effective Date:** [Month Day, Year]","section":null},{"type":"paragraph","text":"Welcome to Lelañea.","section":null},{"type":"paragraph","text":"These Terms of Use (“Terms”) govern your access to and use of the Lelañea application, website, services, educational content, coaching materials, guided meditations, journaling tools, artificial intelligence features, community features, and all related content (collectively, the “Services”).","section":null},{"type":"paragraph","text":"By creating an account, accessing, downloading, or using Lelañea, you acknowledge that you have read, understood, and agree to be legally bound by these Terms.","section":null},{"type":"paragraph","text":"If you do not agree with these Terms, you should not use Lelañea.","section":null},{"type":"heading","text":"About Lelañea","level":2,"number":1,"section":null},{"type":"paragraph","text":"Lelañea is an educational and transcendental coaching platform created by **Lelañea Fulton**, Professional Certified Coach (PCC), Transcendental Coach, and Unity-Consciousness Guide.","section":null},{"type":"paragraph","text":"The Services are intended solely for education, self-reflection, personal development, contemplative practice, and coaching.","section":null},{"type":"paragraph","text":"Lelañea is not a healthcare provider and does not provide medical, psychological, psychiatric, or psychotherapeutic services.","section":null},{"type":"heading","text":"Eligibility","level":2,"number":2,"section":null},{"type":"paragraph","text":"You must be at least eighteen (18) years of age, or the age of legal majority in your jurisdiction, to create an account unless otherwise permitted under applicable law and with any required parental or guardian consent.","section":null},{"type":"paragraph","text":"By using Lelañea, you represent that you have the legal authority to enter into these Terms.","section":null},{"type":"heading","text":"Educational Purpose Only","level":2,"number":3,"section":null},{"type":"paragraph","text":"All content within Lelañea is provided solely for educational, informational, contemplative, and personal development purposes.","section":null},{"type":"paragraph","text":"Nothing contained within the Services should be interpreted as:","section":null},{"type":"list","style":"unordered","items":["medical advice;","psychological advice;","psychiatric advice;","legal advice;","financial advice;","diagnosis;","treatment;","psychotherapy; or","counseling."],"section":null},{"type":"paragraph","text":"Users remain solely responsible for their own decisions, actions, and wellbeing.","section":null},{"type":"heading","text":"No Professional Healthcare Relationship","level":2,"number":4,"section":null},{"type":"paragraph","text":"Your use of Lelañea does not create:","section":null},{"type":"list","style":"unordered","items":["a physician-patient relationship;","psychologist-patient relationship;","psychiatrist-patient relationship;","therapist-client relationship;","counselor-client relationship; or","any other licensed healthcare relationship."],"section":null},{"type":"paragraph","text":"No healthcare services are provided through Lelañea.","section":null},{"type":"heading","text":"Coaching Relationship","level":2,"number":5,"section":null},{"type":"paragraph","text":"Lelañea provides educational coaching experiences.","section":null},{"type":"paragraph","text":"Coaching is not therapy.","section":null},{"type":"paragraph","text":"Coaching is not psychotherapy.","section":null},{"type":"paragraph","text":"Coaching is not psychiatric treatment.","section":null},{"type":"paragraph","text":"Coaching does not diagnose or treat mental illness.","section":null},{"type":"paragraph","text":"Any coaching provided through Lelañea is intended solely to support personal growth, self-awareness, reflection, values exploration, and conscious living.","section":null},{"type":"heading","text":"Personal Responsibility","level":2,"number":6,"section":null},{"type":"paragraph","text":"You acknowledge that you are solely responsible for:","section":null},{"type":"list","style":"unordered","items":["your decisions;","your interpretations;","your physical health;","your mental health;","your emotional wellbeing;","your actions; and","any outcomes resulting from your use of Lelañea."],"section":null},{"type":"paragraph","text":"No specific results are promised or guaranteed.","section":null},{"type":"heading","text":"Crisis Situations","level":2,"number":7,"section":null},{"type":"paragraph","text":"Lelañea is not intended for crisis intervention.","section":null},{"type":"paragraph","text":"If you are experiencing thoughts of suicide, self-harm, harming another person, or any mental health emergency, discontinue use of the Services immediately and contact emergency services or an appropriate crisis resource in your location.","section":null},{"type":"paragraph","text":"Do not rely upon Lelañea during an emergency.","section":null},{"type":"heading","text":"Artificial Intelligence","level":2,"number":8,"section":null},{"type":"paragraph","text":"Some features within Lelañea may utilize artificial intelligence.","section":null},{"type":"paragraph","text":"AI-generated responses are created through automated systems and may occasionally contain inaccuracies, omissions, or content that does not apply to your individual circumstances.","section":null},{"type":"paragraph","text":"AI responses are educational in nature and should never be considered medical, psychological, psychiatric, legal, financial, or professional advice.","section":null},{"type":"paragraph","text":"Users are encouraged to exercise independent judgment and consult qualified professionals whenever appropriate.","section":null},{"type":"heading","text":"Spiritual and Philosophical Content","level":2,"number":9,"section":null},{"type":"paragraph","text":"Lelañea explores consciousness, contemplative traditions, meditation, Advaita Vedanta, Unity Consciousness, Hermetic philosophy, symbolism, and other philosophical or spiritual perspectives.","section":null},{"type":"paragraph","text":"These perspectives are offered for reflection and exploration.","section":null},{"type":"paragraph","text":"They are not presented as universally accepted scientific or medical facts.","section":null},{"type":"paragraph","text":"Users are encouraged to engage with all material thoughtfully and exercise their own discernment.","section":null},{"type":"heading","text":"Intellectual Property","level":2,"number":10,"section":null},{"type":"paragraph","text":"Unless otherwise indicated, all original content created specifically for Lelañea—including text, graphics, audio recordings, videos, coaching frameworks, guided experiences, proprietary exercises, branding, logos, software, and design—is the intellectual property of Lelañea Fulton and Lelañea and is protected under applicable copyright, trademark, and intellectual property laws.","section":null},{"type":"paragraph","text":"Nothing within these Terms transfers ownership of any intellectual property to users.","section":null},{"type":"paragraph","text":"Users may not reproduce, distribute, modify, publish, sell, sublicense, or commercially exploit Lelañea content without prior written permission.","section":null},{"type":"paragraph","text":"Where Lelañea incorporates or adapts concepts influenced by third-party authors, researchers, philosophical traditions, or established methodologies, those influences are acknowledged separately in “The Lineage of Lelañea.”","section":null},{"type":"heading","text":"User Content","level":2,"number":11,"section":null},{"type":"paragraph","text":"Users retain ownership of the journals, reflections, writings, and other original content they create within Lelañea.","section":null},{"type":"paragraph","text":"By submitting content to the platform, users grant Lelañea a limited license necessary to store, process, and display that content for the purpose of providing the Services.","section":null},{"type":"paragraph","text":"Lelañea does not claim ownership of users’ personal writings.","section":null},{"type":"heading","text":"Privacy","level":2,"number":12,"section":null},{"type":"paragraph","text":"Your use of Lelañea is also governed by the Lelañea Privacy Policy.","section":null},{"type":"heading","text":"Limitation of Liability","level":2,"number":13,"section":null},{"type":"paragraph","text":"To the fullest extent permitted by applicable law, Lelañea Fulton, Lelañea, its employees, contractors, affiliates, licensors, and service providers shall not be liable for any direct, indirect, incidental, consequential, special, exemplary, or punitive damages arising from or related to your use of the Services.","section":null},{"type":"paragraph","text":"This includes, but is not limited to:","section":null},{"type":"list","style":"unordered","items":["emotional distress;","personal injury;","business interruption;","data loss;","lost profits;","reliance upon educational content;","decisions made by users; or","inability to access the Services."],"section":null},{"type":"paragraph","text":"Some jurisdictions do not allow certain limitations of liability. In those jurisdictions, these limitations will apply only to the extent permitted by law.","section":null},{"type":"heading","text":"No Warranties","level":2,"number":14,"section":null},{"type":"paragraph","text":"Lelañea is provided on an “as is” and “as available” basis.","section":null},{"type":"paragraph","text":"No warranties, express or implied, are made regarding:","section":null},{"type":"list","style":"unordered","items":["uninterrupted availability;","accuracy;","completeness;","reliability;","suitability for a particular purpose; or","specific outcomes."],"section":null},{"type":"heading","text":"Changes to the Services","level":2,"number":15,"section":null},{"type":"paragraph","text":"Lelañea may modify, suspend, update, or discontinue features of the Services at any time without prior notice.","section":null},{"type":"heading","text":"Modifications to These Terms","level":2,"number":16,"section":null},{"type":"paragraph","text":"These Terms may be updated periodically.","section":null},{"type":"paragraph","text":"Continued use of Lelañea following any update constitutes acceptance of the revised Terms.","section":null},{"type":"heading","text":"Governing Law","level":2,"number":17,"section":null},{"type":"paragraph","text":"These Terms shall be governed by and interpreted in accordance with the laws of the jurisdiction in which Lelañea is legally organized, without regard to conflict-of-law principles.","section":null},{"type":"paragraph","text":"Any disputes arising from these Terms shall be resolved in the appropriate courts of that jurisdiction, unless otherwise required by applicable law.","section":null},{"type":"heading","text":"Severability","level":2,"number":18,"section":null},{"type":"paragraph","text":"If any provision of these Terms is found to be unenforceable or invalid, the remaining provisions shall remain in full force and effect.","section":null},{"type":"heading","text":"Entire Agreement","level":2,"number":19,"section":null},{"type":"paragraph","text":"These Terms constitute the entire agreement between Lelañea and its users regarding the Services and supersede all prior communications relating to the subject matter herein.","section":null},{"type":"heading","text":"Contact","level":2,"number":20,"section":null},{"type":"paragraph","text":"Questions regarding these Terms may be directed to:","section":null},{"type":"paragraph","text":"**Lelañea**","section":null},{"type":"paragraph","text":"Email: [Support Email]","section":null},{"type":"paragraph","text":"Website: lelanea.com","section":null},{"type":"paragraph","text":"By selecting **“I Agree”**, creating an account, or continuing to use Lelañea, you acknowledge that you have read, understood, and agreed to these Terms of Use.","section":null}],"version":"1.1","locale":"en-US"}]}$t86$::jsonb AS "s";

INSERT INTO "app_document_collection" ("id", "title", "version", "locale", "createdAt", "updatedAt")
SELECT
  "s"->'collection'->>'id',
  "s"->'collection'->>'title',
  "s"->'collection'->>'version',
  "s"->'collection'->>'locale',
  now(),
  now()
FROM "_t86_seed"
WHERE NOT EXISTS (SELECT 1 FROM "app_document_collection");

INSERT INTO "app_foundational_document" (
  "id", "collectionId", "position", "title", "subtitle", "category", "surface",
  "requiresAcknowledgement", "placeholders", "renderStyle", "renderNote", "blocks",
  "version", "locale", "revision", "createdAt", "updatedAt"
)
SELECT
  "d"->>'id',
  "s"->'collection'->>'id',
  ("d"->>'position')::int,
  "d"->>'title',
  "d"->>'subtitle',
  "d"->>'category',
  "d"->>'surface',
  ("d"->>'requiresAcknowledgement')::boolean,
  ARRAY(SELECT jsonb_array_elements_text("d"->'placeholders')),
  "d"->>'renderStyle',
  "d"->>'renderNote',
  "d"->'blocks',
  "d"->>'version',
  "d"->>'locale',
  1,
  now(),
  now()
FROM "_t86_seed", jsonb_array_elements("s"->'documents') AS "d"
WHERE NOT EXISTS (SELECT 1 FROM "app_foundational_document");

-- Revision 1 for every document still at revision 1 that has none: a snapshot of
-- the row as written above, with every field "changed", as the seed records it.
INSERT INTO "app_foundational_document_revision" (
  "id", "documentId", "revision", "position", "title", "subtitle", "category",
  "surface", "requiresAcknowledgement", "placeholders", "renderStyle", "renderNote",
  "blocks", "version", "locale", "changedFields", "origin", "editorId", "changedAt"
)
SELECT
  gen_random_uuid()::text, "doc"."id", 1, "doc"."position", "doc"."title",
  "doc"."subtitle", "doc"."category", "doc"."surface", "doc"."requiresAcknowledgement",
  "doc"."placeholders", "doc"."renderStyle", "doc"."renderNote", "doc"."blocks",
  "doc"."version", "doc"."locale",
  ARRAY['position', 'title', 'subtitle', 'category', 'surface', 'requiresAcknowledgement', 'placeholders', 'renderStyle', 'renderNote', 'blocks', 'version', 'locale'],
  'seed', NULL, now()
FROM "app_foundational_document" AS "doc"
WHERE "doc"."revision" = 1
  AND NOT EXISTS (
    SELECT 1 FROM "app_foundational_document_revision" AS "r" WHERE "r"."documentId" = "doc"."id"
  );

DROP TABLE "_t86_seed";
